insert into public.collections (id, name, slug, description, hero_image_url) values
  (1, 'Balenciaga', 'balenciaga', 'Founded by Cristobal Balenciaga in 1917, the Balenciaga House is defined by a worldwide recognition as a leader in major fashion trends due to its creativity, masterful cuts and exquisite techniques. Since October 2015, Demna Gvasalia, appointed artistic director of Balenciaga''s collections, continues to uphold the vision, influence and radical style of the House.', '/mirror-assets/4c65bd82e1dd0e4a.webp'),
  (2, 'Saint Laurent', 'saint-laurent', 'Founded in 1961, Yves Saint Laurent was the first couture house to introduce the concept of luxury prêt-à-porter in a 1966 collection called « Rive Gauche », synonymous with youth and freedom. This shift represented a first critical step in the modernization of fashion and revolutionized the socio-cultural landscape.', '/mirror-assets/457fbb649cc1039b.webp'),
  (3, 'Gucci', 'gucci', 'Founded in Florence in 1921, Gucci is one of the world''s leading luxury fashion brands. At the beginning of 2015, Gucci embarked on the next chapter in its history, under the creative direction of Alessandro Michele, with the introduction of a new contemporary vision, which is re-establishing its reputation as one of the world''s most influential luxury fashion brands. Eclectic, romantic, and above all contemporary, Gucci is currently inventing a wholly modern approach to fashion and thereby redefining luxury for the 21st century.', '/mirror-assets/cc4c0d0871235ba0.webp'),
  (4, 'Dita', 'dita', 'Discover the epitome of luxury eyewear with Dita sunglasses. Experience exquisite craftsmanship and timeless elegance in every pair. Elevate your style with these iconic designer shades. Shop now and embrace the allure of Dita sunglasses.', '/mirror-assets/58efa6e692466a92.webp'),
  (5, 'Valentino', 'valentino', 'Unleash your sense of glamour with Valentino sunglasses. Discover a captivating collection that embodies the essence of luxury and sophistication. From elegant frames to intricate detailing, our Valentino sunglasses exude timeless beauty and refined style. Experience the perfect blend of fashion and craftsmanship as you explore our curated selection. Embrace the allure of Valentino and elevate your look with these statement-making shades.', '/mirror-assets/d7d0d14a8972056e.webp'),
  (6, 'Tom Ford', 'tom-ford', 'Each eyewear frame by Tom Ford is made of high-quality materials like metal, acetate, and nylon-based plastic which are stronger, flexible, and more long-lasting as compared to regular plastic. The sturdy frames are wear-resistant and such is the durability that even second-hand Tom Ford glasses are worth purchasing.', '/mirror-assets/26ae9f4a41703763.webp'),
  (7, 'Cazal', 'cazal', 'Cazal frames serve as a canvas for showy gold, flashy silver, and crystal clear styling, together with classic tortoiseshell and gorgeous marbled coloring. The most exquisite frames in the Cazal collection are gold or silver plated, for a jewelry-like quality.', '/mirror-assets/2d289155bf4f9886.webp'),
  (8, 'Balmain', 'balmain', 'Each pair of designer glasses from this range embodies the elegant and daring spirit which has characterized the house ever since it was founded over 75 years ago. Pierre Balmain’s aesthetic codes are present in each of the new designs and Olivier Rousteing has incorporated an eminently contemporary vision by putting his heart and soul into this accessory which is an essential for any modern woman.', '/mirror-assets/a75460caf85f93ba.webp'),
  (9, 'Montblanc', 'montblanc', 'Montblanc designs and crafts functional, sophisticated products for creative and inspired individuals who challenge the status quo and explore life through different perspectives. Inspired by the Mont Blanc - the highest peak in Europe - Montblanc has been disrupting the world of luxury with audacity, excellence and substance since 1906, first with the invention of revolutionary writing instruments, then with timepieces, leather goods, accessories, fragrances, eyewear and wearable technology.', '/mirror-assets/43328fa8960b362f.webp'),
  (10, 'Maybach', 'maybach', 'MAYBACH eyewear is individually handcrafted in Germany, with high-quality lenses from Zeiss. Customers can also choose to customize their frames with diamonds for a truly unique piece.', '/mirror-assets/93a3275f50c7decd.webp'),
  (11, 'Prada', 'prada', 'Step into the world of luxury with PRADA sunglasses. Discover an exquisite collection that seamlessly combines timeless elegance with innovative design. From sleek frames to iconic details, our PRADA sunglasses epitomize sophistication and style. Experience the perfect blend of fashion and craftsmanship as you explore our curated selection. Indulge in the allure of PRADA and elevate your look with these statement-making shades. Shop now and embrace the essence of high-end eyewear with PRADA.', '/mirror-assets/e22765d8830bda27.webp'),
  (12, 'Miu Miu', 'miu-miu', 'Miu Miu, born under the visionary guidance of Miuccia Prada, carries the essence of her nickname, embodying the lively and creative spirit that defines the brand. Known for its bold approach to fashion, Miu Miu seamlessly blends modern flair with vintage inspirations. Renowned for its intricate designs, distinctive fabrics, and contemporary twist on classic styles, the brand has become a favorite among those who appreciate daring sophistication.', '/mirror-assets/50d36985448002b6.webp'),
  (13, 'Philipp Plein', 'philipp-plein', 'Philipp Plein uses state-of-the-art materials to craft their signature eyewear frames: premium cellulose acetate, ultra-lightweight titanium, and color-rich stainless steel. Philipp Plein lenses are constructed from impact-resistant prescription material and provide 100% UV protection.', '/mirror-assets/415a103125711b8c.webp'),
  (14, 'Cartier', 'cartier', 'Founded in 1847, Cartier is not only one of the most established names in the world of jewelry and watches, it is also a reference of true contemporary luxury. Cartier creates exceptional eyewear, and develops each design from its own vocabulary, showcasing distinctive creativity, exceptional savoir-faire and iconic style led by a clear insight.', '/mirror-assets/55ebf6b19c0e6e13.webp'),
  (15, 'Bottega Veneta', 'bottega-veneta', 'Discretion, quality and unsurpassed craftsmanship - Bottega Veneta has established a new standard of luxury since its founding in the Veneto region of Italy in 1966. Steeped in the traditions of Italian master craftsmen, the house''s artisans create with an extreme attention to detail, high precision and relentless perfectionism. From Bottega Veneta''s atelier - within an 18th century villa in Montebello Vicentino - with their hands, eyes and heart, they turn leather craftsmanship into an art. Bottega Veneta has evolved from a leather goods house to a complete lifestyle brand, expanding its ran', '/mirror-assets/96bdc3b5cd045b18.webp'),
  (16, 'Chopard', 'chopard', 'The styles draw inspiration from the Swiss Maison''s jewelry and watch collections, reinterpreting their most iconic elements in a new medium. The ICE CUBE, IMPERIALE and HAPPY DIAMOND luxury sunglasses collections are the expression of a modern, seductive, naturally elegant woman. Metal sunglasses with precious details. The HAUTE JOAILLERIE RED CARPET Collection returns in a jewelry-inspired, glamorous luxury collection of sunglasses for women – perfect for the most important occasions, such as red carpet events.', '/mirror-assets/e54b9558ae3260ec.webp'),
  (17, 'Versace', 'versace', 'Explore Versace''s luxury optical eyewear collection for men and women, featuring gold-tone metal trims and iconic Medusa elements. With 95 distinct products, including sunglasses, glasses, and shields, available in a variety of styles and colors, you''re sure to find the perfect accessory to complement your unique style. Shop online and experience the elegance and sophistication of Versace eyewear.', '/mirror-assets/placeholder.svg'),
  (18, 'Akoni', 'akoni', 'In 2020, Akoni was founded in Switzerland by a diverse team from across the globe, united by a singular vision: to redefine luxury eyewear. Akoni''s commitment to excellence is reflected in the meticulous approach—choosing only the finest designs, materials, craftsmanship, technologies, and care.', '/mirror-assets/7475a5423639ae5c.webp'),
  (19, 'Page not found', 'page-not-found', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
  (20, 'JP', 'jp', null, '/mirror-assets/fbe4d0af857ff314.webp'),
  (21, 'Page not found', 'page-not-found-21', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
  (22, 'Page not found', 'page-not-found-22', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
