  (26, 'Page not found', 'page-not-found-26', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
  (27, 'Page not found', 'page-not-found-27', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
  (28, 'Page not found', 'page-not-found-28', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
  (29, 'Page not found', 'page-not-found-29', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
  (30, 'Ray-Ban', 'ray-ban', 'Ray-Ban is a globally recognized brand specializing in high-quality sunglasses and eyeglasses. Founded in 1937 by the American company Bausch & Lomb, it gained initial recognition for creating sunglasses specifically for the U.S. Army Air Corps pilots to combat high-altitude glare. These military-inspired shades later became known as the iconic Ray-Ban Aviator style.', '/mirror-assets/2aebcfb0ad09d281.png'),
  (31, 'Armani Exchange', 'armani-exchange', 'Everyday cool with a fresh, feminine twist. This round optical frame pairs a bio-based nylon front with sleek metal temples, finished with the A|X logo. Shiny tones keep it playful, while smooth temple tips bring all-day ease.', '/mirror-assets/fcdf04a515d59b09.avif'),
  (32, 'Polo Ralph Lauren', 'polo-ralph-lauren', 'Polo Ralph Lauren glasses reflect the iconic designer''s vision of classic yet spirited American style for men and women. Timeless and authentic, Ralph Lauren prescription glasses are a symbol of the modern American lifestyle: easy, energetic, and cool.', '/mirror-assets/80b610fcaccd69b3.webp'),
  (33, 'Burberry', 'burberry', 'Burberry eyeglasses blend timeless British elegance with modern design. Known for their iconic style and quality craftsmanship, Burberry frames offer a sophisticated look that works for any occasion', '/mirror-assets/placeholder.svg'),
  (34, 'Page not found', 'page-not-found-34', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
  (35, 'Page not found', 'page-not-found-35', 'Change the way you see the world. Eyewear For All. Get handcrafted pieces that feel tailor-made for your unique features.', '/mirror-assets/c107491cec38ab81.webp'),
  (36, 'Michael Kors', 'michael-kors', 'Michael Kors eyewear blends modern luxury with timeless style. The collection features refined silhouettes, elegant detailing, and versatile designs that combine everyday comfort with a polished, fashion-forward look.', '/mirror-assets/50d775e177644e7e.webp'),
  (37, 'Vogue', 'vogue', 'Vogue Eyewear creates fashion-forward eyewear that blends modern elegance, everyday comfort, and expressive design. The brand is known for stylish frames that help wearers show confidence, personality, and effortless sophistication.', '/mirror-assets/68883bfc26419383.webp'),
  (38, 'Dunhill', 'dunhill', null, null),
  (39, 'Ferrari', 'ferrari', 'Ferrari frames refer to high-performance, stylish eyewear designed in collaboration, featuring materials and design elements inspired by Ferrari racing cars', '/mirror-assets/66ae0851711cba47.avif'),
  (40, 'dolce & gabbana', 'dolce-and-gabbana', null, null),
