insert into public.products (id, slug, name, brand, collection_id, category_id, subcategory_id, model, frame_type, gender, shape, material, color, color_code, size, price, currency, short_description, description, details, path, status, is_featured, is_transitions, sort_order) values
  (8, 'akoni-sagitta-8', 'Akoni Sagitta', 'Akoni', 18, 'optical', 'optical:transitions', 'Sagitta', 'Optical', 'Female', 'Square Full Frame', 'Acetate', 'Black', 'A-52', 'XS', 515, 'USD', 'Experience luxury with Akoni Sagitta AKX-411 Optical.', 'By widening and adding height to the Sagitta frame, Akoni has transformed the cat-eye silhouette, with additional lightness achieved using translucent acetate frames. But the core cat power clearly remains, as Sagitta''s lines help to accentuate cheekbones and give each face a youthful lift.', '{"brand":"Akoni","model":"Sagitta","colorCode":"A-52","shape":"Square Full Frame","frameType":"Optical","gender":"Female","material":"Acetate","size":"XS","color":"Black"}'::jsonb, '/product/8', 'active', false, true, 31),
  (109, 'balenciaga-bb0341o-109', 'Balenciaga BB0341O', 'Balenciaga', 1, 'optical', 'optical:transitions', 'BB0341O', 'Optical', 'Female', 'Cat-Eye Full Frame', 'Recycled Acetate', 'Black', '001', 'M', 415, 'USD', 'Experience luxury with Balenciaga BB0341O Optical.', 'New shapes introduced to expand the assortment of the Power concept, launched in SS21 and inspired by the evolution of cut iconic sharp design. Power cat-eye shape characterized by sharp design and architectural proportions. High relief BB Iconic logo on left temple', '{"brand":"Balenciaga","model":"BB0341O","colorCode":"001","shape":"Cat-Eye Full Frame","frameType":"Optical","gender":"Female","material":"Recycled Acetate","size":"M","color":"Black"}'::jsonb, '/product/109', 'active', false, true, 88),
  (110, 'balenciaga-bb0342o-110', 'Balenciaga BB0342O', 'Balenciaga', 1, 'optical', 'optical:transitions', 'BB0342O', 'Optical', 'Female', 'Cat-Eye Full Frame', 'Recycled Acetate', 'Violet', '007', 'XS', 415, 'USD', 'Experience luxury with Balenciaga BB0342O Optical.', 'New shapes introduced to expand the assortment of the Power concept, launched in SS21 and inspired by the evolution of cut iconic sharp design. Power soft cat-eye shape characterized by sharp design and architectural proportions. High relief BB Iconic logo on left temple.', '{"brand":"Balenciaga","model":"BB0342O","colorCode":"007","shape":"Cat-Eye Full Frame","frameType":"Optical","gender":"Female","material":"Recycled Acetate","size":"XS","color":"Violet"}'::jsonb, '/product/110', 'active', false, true, 87),
  (113, 'balmain-admirable-bps-130a-52-113', 'Balmain Admirable BPS-130A-52', 'Balmain', 8, 'sunglasses', 'sunglasses:transitions', 'Admirable BPS-130A-52', 'Sunglasses', 'Unisex', 'Square', 'Acetate', 'Black', 'BPS-130A', 'L', 755, 'USD', 'Experience luxury with Balmain Admirable BPS-130A-52 Sunglasses.', 'Balmain''s B-Admirable shield design flaunts an audacious silhouette, premium Japanese acetate, and a signature golden touch, echoing luxury and style.', '{"brand":"Balmain","model":"Admirable BPS-130A-52","colorCode":"BPS-130A","shape":"Square","frameType":"Sunglasses","gender":"Unisex","material":"Acetate","size":"L","color":"Black"}'::jsonb, '/product/113', 'active', false, true, 173),
  (114, 'balmain-b-grand-bps-144c-57-114', 'Balmain B-Grand BPS-144C-57', 'Balmain', 8, 'sunglasses', 'sunglasses:transitions', 'B-Grand BPS-144C-57', 'Sunglasses', 'Unisex', 'Square Full Frame', 'Acetate', 'Brown', 'BPS-144C', 'L', 775, 'USD', 'Experience luxury with Balmain B-Grand BPS-144C-57 Sunglasses.', 'Balmain''s B-Grand shield design flaunts an audacious silhouette, premium Japanese acetate, and a signature golden touch, echoing luxury and style.', '{"brand":"Balmain","model":"B-Grand BPS-144C-57","colorCode":"BPS-144C","shape":"Square Full Frame","frameType":"Sunglasses","gender":"Unisex","material":"Acetate","size":"L","color":"Brown"}'::jsonb, '/product/114', 'active', false, true, 175),
  (115, 'balmain-b-muse-bps-151b-55-115', 'Balmain B-Muse BPS-151B-55', 'Balmain', 8, 'sunglasses', 'sunglasses:transitions', 'B-Muse BPS-151B-55', 'Sunglasses', 'Unisex', 'Cat-Eye Full Frame', 'Acetate', 'Red', 'BPS-151B', 'M', 779, 'USD', 'Experience luxury with Balmain B-Muse BPS-151B-55 Sunglasses.', 'Olivier Rousteing draws inspiration from Balmain''s legacy in designing the B-Muse frame. This Japanese acetate creation, with a subtle cat-eye silhouette, pays homage to powerful muses who shaped modern culture. Golden Balmain embellishments and the iconic modern monogram accentuate this fusion of timeless elegance and contemporary allure.', '{"brand":"Balmain","model":"B-Muse BPS-151B-55","colorCode":"BPS-151B","shape":"Cat-Eye Full Frame","frameType":"Sunglasses","gender":"Unisex","material":"Acetate","size":"M","color":"Red"}'::jsonb, '/product/115', 'active', false, true, 176),
  (116, 'balmain-bps-110a-116', 'Balmain BPS 110A', 'Balmain', 8, 'sunglasses', 'sunglasses:transitions', 'BPS 110A', 'Sunglasses', 'Unisex', 'Aviator Full Frame', 'Titanium', 'Black', '110A', 'S', 820, 'USD', 'Experience luxury with Balmain BPS 110A Sunglasses.', 'The BALMAIN BPS 110A 52 are designed for all-day comfort and style. With a full rim round shape, unisex frame, titanium material, and Global Geofit technology, these glasses provide a comfortable fit for any face shape. Constructed from high quality Japanese materials, these glasses offer superior durability and craftsmanship.Keep', '{"brand":"Balmain","model":"BPS 110A","colorCode":"110A","shape":"Aviator Full Frame","frameType":"Sunglasses","gender":"Unisex","material":"Titanium","size":"S","color":"Black"}'::jsonb, '/product/116', 'active', false, true, 177),
  (118, 'balmain-b-vii-118', 'Balmain B-VII', 'Balmain', 8, 'sunglasses', 'sunglasses:transitions', 'B-VII', 'Sunglasses', 'Unisex', 'Square Full Frame', 'Acetate', 'Black', 'BPS 128C', 'M', 950, 'USD', 'Experience luxury with Balmain B-VII Sunglasses.', 'Oversized frame, wide temples, embossed gold-tone Balmain logo on side, gold-tone finishes, gray anti-glare lenses, 100% UV protection', '{"brand":"Balmain","model":"B-VII","colorCode":"BPS 128C","shape":"Square Full Frame","frameType":"Sunglasses","gender":"Unisex","material":"Acetate","size":"M","color":"Black"}'::jsonb, '/product/118', 'active', false, true, 183),
  (119, 'balmain-fixe-bpx-123a-119', 'Balmain Fixe BPX-123A', 'Balmain', 8, 'optical', 'optical:transitions', 'Fixe BPX-123A', 'Optical', 'Unisex', 'Cat-Eye Rimless', 'Acetate', 'Gold', 'BPX-123A', 'M', 850, 'USD', 'Experience luxury with Balmain Fixe BPX-123A Optical.', 'Introducing the Radiant BALMAIN Fixe BPS 123A: Where Gold and Matte Black ConvergeStep into a world of style and allure with the BALMAIN Fixe BPS 123A—a captivating rectangular sunglass that marries the gleam of gold with the sophistication of matte black, adorned with enchanting grey lenses.Evoke the spirit of the ''80s with the Balmain Fixe BPS 123A Sunglasses—a tribute to sleekness and boldness. This distinctive rimless style effortlessly captures the essence often gracing Olivier Rousteing''s iconic Parisian runways. A single glance reveals these sunglasses as a resounding statement, tailored for those who dare to embrace individuality and step beyond the ordinary.With audacious lines and avant-garde craftsmanship, the Fixe sunglasses transcend conventional boundaries with their daring contours. Guided by expert artisans at Akoni, the latest advancements in lens-and-frame engineering converge to give life to this masterpiece. The outcome is a fearless choice for those seeking shield sunglasses, a visual masterpiece that promises a unique and arresting appearance.', '{"brand":"Balmain","model":"Fixe BPX-123A","colorCode":"BPX-123A","shape":"Cat-Eye Rimless","frameType":"Optical","gender":"Unisex","material":"Acetate","size":"M","color":"Gold"}'::jsonb, '/product/119', 'active', false, true, 179),
  (120, 'balmain-formee-bpx-148a-120', 'Balmain Formee BPX-148A', 'Balmain', 8, 'optical', 'optical:transitions', 'Formee BPX-148A', 'Optical', 'Unisex', 'Square Full Frame', 'Titanium', 'Black', 'BPX-148A', 'S', 750, 'USD', 'Experience luxury with Balmain Formee BPX-148A Optical.', 'Introducing the BALMAIN Formee BPX 148A: A Vision of EleganceStep into a world of refined style with the BALMAIN Formee BPX 148A optical masterpiece. This unique creation harmoniously blends a lustrous black backdrop with a frame of opulent gold accents, elevating your optical experience to new heights.Capturing the very essence of Balmain''s iconic blazer, the Formee BPX 148A Optical Glasses pay homage to precision tailoring and artful construction. Inspired by the confident lines and meticulous geometry of the Balmain blazer, these glasses seamlessly translate its essence into eyewear that radiates confidence and sophistication.Crafted as a testament to Balmain''s unwavering dedication to quality, the Formee frame stands as a testament to meticulous craftsmanship. Originating in Japan, a realm renowned for its mastery of eyewear artistry, these optical glasses boast premium Japanese acetate construction. A guarantee of both durability and indulgent comfort, this material whispers luxury against your skin.The Balmain Formee BPX 148A''s oversized curved frame adds a touch of mystique and allure to your visage. Its graceful curvature accentuates your features while projecting an air of bold elegance. Unmistakable in any setting, these glasses command attention effortlessly.From formal affairs to everyday elegance, the BALMAIN Formee BPX 148A Optical Glasses gracefully merge classic tailoring with a contemporary aesthetic. The seamless marriage of bold lines and meticulous geometry births a frame that is an embodiment of distinction and refinement.Indulge in the finesse and artistry of Balmain through the BALMAIN Formee BPX 148A Optical Glasses. Immerse yourself in the oversized, gracefully curved frame that encapsulates the brand''s unwavering pursuit of flawless design. Elevate your look and etch an enduring impression with these extraordinary optical glasses from the house of Balmain.', '{"brand":"Balmain","model":"Formee BPX-148A","colorCode":"BPX-148A","shape":"Square Full Frame","frameType":"Optical","gender":"Unisex","material":"Titanium","size":"S","color":"Black"}'::jsonb, '/product/120', 'active', false, true, 182),
  (121, 'balmain-legion-i-bpx-112a-121', 'Balmain Legion I BPX-112A', 'Balmain', 8, 'optical', 'optical:transitions', 'Legion I BPX-112A', 'Optical', 'Unisex', 'Square Full Frame', 'Acetate', 'Black', 'BPX-112A', 'S', 830, 'USD', 'Experience luxury with Balmain Legion I BPX-112A Optical.', 'Presenting the BALMAIN LEGION - I BPX-112A Unisex Optical Frame: Where Elegance Meets EmpowermentEnter the realm of sophistication with the BALMAIN LEGION - I BPX-112A Unisex Optical Frame—a fusion of gold and black that exudes timeless allure. Inspired by the unwavering confidence of today''s Balmain Army, this frame embodies their vigor and poise, shaping an integral strand of Balmain''s DNA. This indomitable spirit finds a new canvas in Balmain''s designer sunglasses.Discover the genuine allure of Lexor Miami Balmain Paris Sunglasses, an authorized dealer in Miami, where authenticity reigns supreme. Each piece in our collection stands as a testament to originality, guaranteed brand new and sealed in its pristine packaging. When you choose us, you choose a promise of authenticity, as each order arrives with its original case, cloth, and the manufacturers warranty—a testament to the quality that both Lexor Miami and the Balmain Army hold dear.With the BALMAIN LEGION - I BPX-112A Unisex Optical Frame, embrace the fusion of elegance and empowerment. A symphony of gold and black, this frame encapsulates the indomitable spirit that fuels the Balmain Army. Like a legion of style, these optical frames stand as a symbol of unity between bold design and unwavering authenticity, inviting you to embody your unique essence with every wear.', '{"brand":"Balmain","model":"Legion I BPX-112A","colorCode":"BPX-112A","shape":"Square Full Frame","frameType":"Optical","gender":"Unisex","material":"Acetate","size":"S","color":"Black"}'::jsonb, '/product/121', 'active', false, true, 178),
  (122, 'balmain-legion-ii-bpx-113a-122', 'Balmain Legion II BPX-113A', 'Balmain', 8, 'optical', 'optical:transitions', 'Legion II BPX-113A', 'Optical', 'Unisex', 'Cat-Eye', 'Acetate', 'Black', 'BPX-113A', 'S', 760, 'USD', 'Experience luxury with Balmain Legion II BPX-113A Optical.', 'Our dedication was unwavering as we aimed to incorporate a browline frame into this exquisite collection, Olivier Rousteing articulates. Harkening back to the 90s and early 2000s, this style held tremendous prominence, a sentiment embraced by both the Akoni team and myself—a love that endures to this day. Within the Legion II resides the essence of those impassioned and intellectually bold non-conformists, forever intertwined with this aesthetic. It''s no mystery why countless avant-garde musicians have seamlessly embraced this frame across decades—it mirrors their self-assured, distinctively individual style. Its versatility shines whether paired with jeans and a tee or a suave double-breasted jacket. A personal favorite touch of mine is the infusion of our iconic house codes, seamlessly revitalizing this timeless design into an unmistakably Balmain masterpiece', '{"brand":"Balmain","model":"Legion II BPX-113A","colorCode":"BPX-113A","shape":"Cat-Eye","frameType":"Optical","gender":"Unisex","material":"Acetate","size":"S","color":"Black"}'::jsonb, '/product/122', 'active', false, true, 174),
  (123, 'balmain-legion-iii-bpx-132-123', 'Balmain Legion III BPX-132', 'Balmain', 8, 'optical', 'optical:transitions', 'Legion III BPX-132', 'Optical', 'Unisex', 'Square Full Frame', 'Acetate', 'Havana', 'B', 'S', 1000, 'USD', 'Experience luxury with Balmain Legion III BPX-132 Optical.', 'Introducing the Exquisite BALMAIN Legion III BPX 132: A Fusion of OpulenceEnter the realm of refined eyewear with the BALMAIN Legion III BPX 132—an artistic square optical creation adorned in a harmonious black and gold frame, a testament to opulent design.Elevate your eyewear experience to unparalleled heights through the Balmain Legion III BPX-132 Optical Glasses. As a distinguished member of the esteemed Legion frame family, these glasses encapsulate the unparalleled artistry synonymous with Balmain''s prestigious Parisian ateliers. Through a masterful fusion of sumptuous materials and textures, a seamless and sophisticated frame comes to life—a creation that effortlessly captures the gaze.In its third iteration, the Balmain Legion III BPX-132A frame emerges with refined enhancements, boasting a versatile and unisex silhouette. Balmain''s unwavering commitment to innovation takes center stage with the inclusion of captivating titanium mesh side shields. Adorned with the iconic Labyrinth motif, these shields beckon to the brand''s rich legacy and timeless sophistication.The Balmain Legion glasses effortlessly weave the threads of style and functionality. Crafted from premium materials, they stand as a testament to both durability and comfort. With meticulous attention to detail and unwavering craftsmanship, these glasses boast a flawless finish that resonates with luxury.Step into a world where elegance converges with innovation, embracing the enchanting aura of the BALMAIN Legion III BPX 132 Optical Glasses. Let the captivating design become an extension of your spirit, reflecting the essence of Balmain and illuminating your impeccable style.', '{"brand":"Balmain","model":"Legion III BPX-132","colorCode":"B","shape":"Square Full Frame","frameType":"Optical","gender":"Unisex","material":"Acetate","size":"S","color":"Havana"}'::jsonb, '/product/123', 'active', false, true, 185),
  (124, 'balmain-monsieur-bpx-153c-53-124', 'Balmain Monsieur BPX-153C-53', 'Balmain', 8, 'optical', 'optical:transitions', 'Monsieur BPX-153C-53', 'Optical', 'Unisex', 'Half Rimless', 'Acetate', 'Gold', 'BPX-113A', 'S', 965, 'USD', 'Experience luxury with Balmain Monsieur BPX-153C-53 Optical.', 'The Unisex BALMAIN Glasses MONSIEUR (MONSIEUR BPX-153C-53) feature a yellow gold medium brown swirl frame. Improve your vision with transparent lenses. Comes with an official BALMAIN Glasses 1-year guarantee.', '{"brand":"Balmain","model":"Monsieur BPX-153C-53","colorCode":"BPX-113A","shape":"Half Rimless","frameType":"Optical","gender":"Unisex","material":"Acetate","size":"S","color":"Gold"}'::jsonb, '/product/124', 'active', false, true, 184),
  (125, 'balmain-olivier-bps-159-125', 'Balmain Olivier BPS-159', 'Balmain', 8, 'sunglasses', 'sunglasses:transitions', 'Olivier BPS-159', 'Sunglasses', 'Female', 'Round Full Frame', 'Acetate', 'Black', 'A-42', 'XS', 915, 'USD', 'Experience luxury with Balmain Olivier BPS-159 Sunglasses.', 'The Balmain Olivier BPS-159A-42 sunglasses are a must-have accessory that can be paired with any outfit and are suitable for everyday use. They have a 42 mm lens width, a round and oval silhouette, and are unisex. They come with the original case, a cleaning cloth, a certificate of authenticity, and a guarantee', '{"brand":"Balmain","model":"Olivier BPS-159","colorCode":"A-42","shape":"Round Full Frame","frameType":"Sunglasses","gender":"Female","material":"Acetate","size":"XS","color":"Black"}'::jsonb, '/product/125', 'active', false, true, 180),
  (126, 'balmain-sentinelle-iii-bpx-119-126', 'Balmain Sentinelle III BPX-119', 'Balmain', 8, 'optical', 'optical:transitions', 'Sentinelle III BPX-119', 'Optical', 'Unisex', 'Cat-Eye Full Frame', 'Acetate', 'Havana', 'B', 'S', 650, 'USD', 'Experience luxury with Balmain Sentinelle III BPX-119 Optical.', 'Presenting the Balmain Sentinelle III BPX-119A Optical Glasses: A Symphony of EleganceIndulge in the captivating fusion of black and gold with the Balmain Sentinelle III BPX-119A Optical Glasses. This exquisite square-shaped optical creation effortlessly combines these hues to craft an accessory that radiates sophistication.Introducing the Balmain Sentinelle III BPX-119A Optical Glasses—a reimagined ode to the timeless cat-eye shape, celebrated for its flattering allure in women''s eyewear. Born from meticulous craftsmanship and originating in the artisanal realm of Japan, these glasses bear the quintessential Balmain touch, making them a true embodiment of elegance.Behold the Sentinelle III frames, a canvas that artfully captures the essence of femininity and refinement. The fluid lines of the cat-eye shape are elegantly heightened by Balmain''s distinctive style, culminating in a frame that emanates poise and confidence.Crafted with unwavering attention to detail in Japan, these optical glasses pay homage to the precision that defines Balmain. Each meticulous facet of the Balmain Sentinelle III BPX-119A speaks volumes about the brand''s commitment to exceptional craftsmanship. Impeccable materials ensure longevity and comfort, enabling you to relish in both style and practicality.With the Balmain Sentinelle III BPX-119A Optical Glasses, you wield the power to effortlessly elevate your everyday ensemble or make a bold statement during momentous occasions. These glasses stand as a testament to the affinity for timeless design held by women who wish to express their uniqueness with grace.Embark on a journey into the realm of Balmain, embracing the irresistible charm of the Sentinelle III. Unveil a harmonious blend of masterful artistry, flattering aesthetics, and the very essence of Balmain''s legacy. Let these optical glasses mirror your style and elevate your visual narrative with their enchanting sophistication.', '{"brand":"Balmain","model":"Sentinelle III BPX-119","colorCode":"B","shape":"Cat-Eye Full Frame","frameType":"Optical","gender":"Unisex","material":"Acetate","size":"S","color":"Havana"}'::jsonb, '/product/126', 'active', false, true, 181),
  (168, 'cartier-ct0061o-168', 'Cartier CT0061O', 'Cartier', 14, 'optical', 'optical:transitions', 'CT0061O', 'Optical', 'Unisex', 'Rimless', 'Metal', 'Silver', '003', 'M', 1345, 'USD', 'Experience luxury with Cartier CT0061O Optical.', 'Classical rectangular rimless feminine shape, featuring the emblematic Panthère de Cartier for an audacious and glamorous design. Precious pouncing panther sculpture on a slender temple with pure and dynamic lines. Precious finishes in gold, platinum or ruthenium. Precious finishes (gold, platinum and ruthenium) adorning the decor and the bronze temples.', '{"brand":"Cartier","model":"CT0061O","colorCode":"003","shape":"Rimless","frameType":"Optical","gender":"Unisex","material":"Metal","size":"M","color":"Silver"}'::jsonb, '/product/168', 'active', false, true, 16),
