  (281, 'cazal-8509-281', 'Cazal 8509', 'Cazal', 7, 'sunglasses', 'sunglasses:transitions', '8509', 'Sunglasses', 'Unisex', 'Square Full Frame', 'Acetate', 'Transparent', '004', 'XL', 650, 'USD', 'Experience luxury with Cazal 8509 Sunglasses.', 'This is a brand new unworn authentic Cazal Sunglasses. Model 8509', '{"brand":"Cazal","model":"8509","colorCode":"004","shape":"Square Full Frame","frameType":"Sunglasses","gender":"Unisex","material":"Acetate","size":"XL","color":"Transparent"}'::jsonb, '/product/281', 'active', false, true, 163),
  (284, 'cazal-legends-644-284', 'Cazal Legends 644', 'Cazal', 7, 'sunglasses', 'sunglasses:transitions', 'Legends 644', 'Sunglasses', 'Unisex', 'Round Full Frame', 'Acetate', 'Black', '001', 'M', 540, 'USD', 'Experience luxury with Cazal Legends 644 Sunglasses.', 'The “644” introduced in 1991 has now, like the CAZAL “642”, been relaunched with a modern crystal variant, in addition to the classic colours of Black and Havana. With the austere architecture of the “644” and the ingenious combination of graphic elements, Cari Zalloni created an eyewear icon that has become a cult.', '{"brand":"Cazal","model":"Legends 644","colorCode":"001","shape":"Round Full Frame","frameType":"Sunglasses","gender":"Unisex","material":"Acetate","size":"M","color":"Black"}'::jsonb, '/product/284', 'active', false, true, 56),
  (294, 'dita-sequoia-optical-294', 'Dita Sequoia Optical', 'Dita', 4, 'optical', 'optical:transitions', 'Sequoia Optical', 'Optical', 'Unisex', 'Square Full Frame', 'Acetate', 'Black', 'DRX-2086C-NVY-54', 'S', 450, 'USD', 'Experience luxury with Dita Sequoia Optical Optical.', 'One of my earliest memories as a child was seeing the General Sherman tree on a family vacation to Sequoia National Park. Years later, words still cannot capture the immensity of this natural marvel; I designed this frame to convey the same grand scale and feeling of durability that sparked my love for the natural world at such a young age.', '{"brand":"Dita","model":"Sequoia Optical","colorCode":"DRX-2086C-NVY-54","shape":"Square Full Frame","frameType":"Optical","gender":"Unisex","material":"Acetate","size":"S","color":"Black"}'::jsonb, '/product/294', 'active', false, true, 29),
