  ('208d1e3e-a3cc-aff1-293d-f7faf14dee0e', 5996, 'Dita Artoa.79', 'Aviator', 'Sunglasses', 'Titanium', 'Black', 'DTS161-A-03', '/mirror-assets/ff227032bc818119.png', 'Dita Artoa.79', 595, 'USD', null, 146),
  ('ca795066-9ffc-420c-82f0-c0113a31821f', 6001, 'Dita Artoa.27', 'Classic', 'Sunglasses', null, 'Silver', 'DTS163-A-01', '/mirror-assets/59563635cd138edd.png', 'Dita Artoa.27', 595, 'USD', null, 147),
  ('139c001d-7669-b64d-eb18-0fdc374e64e8', 6005, 'Dita Grand-Deus', 'Classic', 'Sunglasses', 'Acetate', 'White Gold', 'DTX488-A-03', '/mirror-assets/e07273d40ea6e05b.png', 'Dita Grand-Deus', 1205, 'USD', 'GRAND-DEUS pushes rimless design into a new realm of technical sophistication through an intricate titanium construction and precision-engineered detailing. Featuring a custom titanium nose bridge and brow bar with screw-mounted lenses accented by colored nylor thread, the frame balances structural minimalism with elevated complexity. Finished with diamond-pressed hinge detailing, enamel inlay accents, and sculpted Japanese acetate temples, GRAND-DEUS is handcrafted in Japan as a bold expression of modern optical engineering.', 6),
  ('6312caf8-8e27-99ff-7aec-2601fc6cca70', 6006, 'Maybach The Visionist Sun I', 'Classic', 'Sunglasses', null, 'Gold', 'MM-VISS01M-WEOM09-6017', '/mirror-assets/099062e4e324a84a.png', 'Maybach The Visionist Sun I', 3135, 'USD', null, 3)
