insert into public.faqs (id, category, question, answer, sort_order, is_active) values
  ('1f6f4abc-790a-7a4e-11eb-41fc83e76212', 'shipping', 'Do you deliver products outside the United States?', 'No, we only deliver within the USA.', 0, true),
  ('733a0281-da86-18ec-7713-08d5e614388f', 'lenses', 'How do I add a prescription to my order?', 'Register and log into your account, add the prescription in your profile, and select the added prescription in your cart.', 1, true),
  ('174effe7-ffc7-f4cd-2cfa-e62e8497f649', 'lenses', 'How can I create my own .custom lenses?', 'Use our .custom lens service in our store. You can choose the material, color, and other lens parameters.', 2, true),
  ('03e2839b-23ba-d9d3-ce61-ea94a052771c', 'shipping', 'What is the delivery time for glasses?', 'Standard delivery takes 5-10 business days. Express delivery is available for an additional fee and takes 1 business day.', 3, true),
  ('bbd458c9-de54-04e0-36cf-45d812b67f6a', 'returns', 'Do you accept returns or exchanges?', 'Some items may be eligible, but custom lenses, prescription lenses, electronics, and gift cards are non-returnable and non-refundable. Please review our Store Policy or contact support.', 4, true),
  ('6c8c03c2-e09a-10b0-9c29-0a5e53c5929b', 'care', 'How should I care for my glasses?', 'We recommend cleaning the lenses with a special microfiber cloth. Store your glasses in a case when not in use. Avoid contact with chemicals and don''t leave your glasses in direct sunlight.', 5, true),
  ('fca10d73-304d-0328-624b-16fc4169e2c8', 'authenticity', 'How can I verify that brand-name glasses are authentic?', 'All our brand-name glasses are supplied directly from official manufacturers and come with certificates of authenticity. Each pair comes with an original case and documentation.', 6, true)
insert into public.reviews (id, author_name, rating, body, source, status, is_verified, reviewed_at, metadata) values
  ('80b39f75-5a67-d75b-aa58-3848dd4f1f72', 'Mae Jae', 5, 'Manny is fantastic! He personally reached out and took the time to understand exactly what I was looking for, making sure I got just what I wanted. I truly appreciate his attention to detail and excellent service!', 'google', 'approved', false, now(), '{"relativeDate":"2 weeks ago","importedFrom":"homepage"}'::jsonb),
  ('67726790-7fda-e22c-9614-50611cb2c146', 'Rich Bartley', 5, 'I was searching for several months for a particular Maybach Artist III colorway and wasn''t able to find it. I stumbled across one of Manny''s videos for Art of Optics and I reached out to him. Manny went above and beyond and was able to get the ones that no one else could find. When he received the glasses, he sent a video and reached out to me on video chat. I received the glasses a few days later. If you want exceptional service, I highly recommend. Thanks again Manny!', 'google', 'approved', false, now(), '{"relativeDate":"3 weeks ago","importedFrom":"homepage"}'::jsonb),
  ('f92cc421-69f5-6aab-8d67-de711d9fda75', 'Sour Diesel', 5, 'Best place to go to, will not pressure you to buy and always guides you through the whole process. Preciate your buisness!!!', 'google', 'approved', false, now(), '{"relativeDate":"3 weeks ago","importedFrom":"homepage"}'::jsonb),
  ('13020f62-5e4c-3cdc-cfed-643f98d1f00a', 'Gary Khaim', 5, 'Excellent service at Art of Optics! Manny helped me pick up a pair of Maybach glasses that I first saw Drake wearing, and I couldn’t be happier with them. If you’re looking for high-end eyewear, go see Manny! He has really cool selection.', 'google', 'approved', false, now(), '{"relativeDate":"2 months ago","importedFrom":"homepage"}'::jsonb),
  ('05e4ce97-b1a5-4086-bd18-befec9a3c0e9', 'Kenny Jeudi', 5, 'My experience with JP has been absolutely wonderful. Despite being 2 hours away from me, I continue to use him because of his impeccable service and trustworthiness. I have purchased 3 pairs of glasses and lenses from Manny. He is very knowledgeable, patient, and has so much variety its hard to choose just one. The quality is on point, and he has even fixed and revived glasses other establishments did subpar with. JP is highly recommended.', 'google', 'approved', false, now(), '{"relativeDate":"2 months ago","importedFrom":"homepage"}'::jsonb),
  ('0aa34ca6-7f50-58f6-b95c-72a30a8e4d32', 'Jonathan Gavrielov', 5, 'Amazing selection and amazing customer service. This store has the best selection of high-end optical frames and sunglasses that I have ever seen. Be sure to ask for the Manny special.', 'google', 'approved', false, now(), '{"relativeDate":"2 months ago","importedFrom":"homepage"}'::jsonb),
  ('6ff599f5-ff87-c5ea-f2cb-d833b067c0fe', 'Geo Silva', 5, 'This place is great. They have a wide variety of frames and an infinite amount of options as far as customization goes. Manny is extremely helpful, knows his stuff and takes the time out to get a sense of your own personal style and needs and then executes. The work done is immaculate. I have bought quite a few frames from here and plan on getting more some time soon.', 'google', 'approved', false, now(), '{"relativeDate":"2 months ago","importedFrom":"homepage"}'::jsonb),
  ('da5c3672-9013-8a97-e98a-05a6647aa5b8', 'manuel crum', 5, 'Hands down best doing it in his own lane. Im 3 pair in and plotting on my next buy. Its simple inbox/call, place order and Manny always gives his best advice and customer service. From Milwaukee to Harlem wishing Art Of Optics the success and notoriety they deserve', 'google', 'approved', false, now(), '{"relativeDate":"2 months ago","importedFrom":"homepage"}'::jsonb),
  ('1d6cecac-3e0d-e9dc-9e2a-62487a0c13df', 'Jonathan Davydov', 5, 'Informative, quick, easy seamless process. This is how my experience with JP was. GO see Manny for all your Eyewear needs', 'google', 'approved', false, now(), '{"relativeDate":"2 months ago","importedFrom":"homepage"}'::jsonb),
  ('f2ba816a-0d2e-5699-7a12-752e5cffccaf', 'Mista Mista', 5, 'Came to JP in need of new hinges and lenses and Manny did his thing on my Woods. EXCELLENT WORK', 'google', 'approved', false, now(), '{"relativeDate":"2 months ago","importedFrom":"homepage"}'::jsonb),
  ('bfde42e7-3504-c0b2-7137-02a9f23e294a', 'john Kim', 5, 'Manny got an amazing team! They got me my custom lenses made and shipped within a week! Video chatted me to make sure every step of the process was smooth as butter!', 'google', 'approved', false, now(), '{"relativeDate":"10 months ago","importedFrom":"homepage"}'::jsonb),
  ('a74e429b-0f8b-948c-554c-45fab6f9fa35', 'JD', 5, 'Always great working with Manny. Real great work and quality. Purchased a pair of prescription lenses and they arrived in fantastic shape. Manny took care of everything I needed and got me right just in time for my birthday. Don’t hesitate to get anything from JP!', 'google', 'approved', false, now(), '{"relativeDate":"a year ago","importedFrom":"homepage"}'::jsonb),
  ('7a5ee51f-e59f-bb04-49ff-32b157f7a274', 'arthur simontobov', 5, 'Finally got my hands on my first pair of Cartier glasses, and I couldn''t be happier! After years of admiring them from afar, I decided to treat myself, and it was worth every penny. The craftsmanship, the elegance – it''s truly unmatched. Thanks to Manny at JP for helping me find the perfect pair!', 'google', 'approved', false, now(), '{"relativeDate":"2 years ago","importedFrom":"homepage"}'::jsonb),
  ('9cc76eb4-725d-999a-feb6-bf40091bb7bd', 'J M', 5, 'Manny was very professional and took care of me with no issues!! If you are looking for a pair of Cartiers or any other designer glasses this is the place you want to check out for sure. They have a Endless selection that you can choose from so i highly recommend!!', 'google', 'approved', false, now(), '{"relativeDate":"2 years ago","importedFrom":"homepage"}'::jsonb),
  ('08774883-182f-ed01-13c7-a046f05baf2e', 'ImSoFreshSoClean1', 5, 'I found this place on IG and decided to see what the hype was about upon arrival to JP I was greeted with staff that was extremely friendly and knowledgable to the questions I had then I was introduced to Manny who transformed my Cartier frames with his skill and expertise I can’t seem to put these Cartier frames down', 'google', 'approved', false, now(), '{"relativeDate":"2 years ago","importedFrom":"homepage"}'::jsonb)
